<?php
/* Phase 328: dedicated transparent 4K images for Snowa refrigerator v327. */
add_action('init',function(){
 if(get_option('bhc_catalog_image_snowa_refrigerator_remediation_v328'))return;
 @ini_set('memory_limit','768M');$base=__DIR__.'/';$upload=wp_upload_dir();$map=[968=>['model'=>'sbdi-s100sw','file'=>'snowa-sbdi-s100sw-v328-source.png'],970=>['model'=>'s1di-m200','file'=>'snowa-s1di-m200-v328-source.png']];foreach(['BHC-SNOWA-S1DI-S100'=>['model'=>'s1di-s100','file'=>'snowa-s1di-s100-v328-source.png'],'BHC-SNOWA-S1DI-L300'=>['model'=>'s1di-l300','file'=>'snowa-s1di-l300-v328-source.png']] as $sku=>$it){$id=wc_get_product_id_by_sku($sku);if($id)$map[$id]=$it;}
 foreach($map as $id=>$it){$src=$base.$it['file'];if(!is_readable($src))continue;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$im=@imagecreatefrompng($src);if(!$im)continue;$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=(int)round($w*$scale);$nh=(int)round($h*$scale);$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);$c=imagecolorallocatealpha($out,0,0,0,127);imagefilledrectangle($out,0,0,$nw,$nh,$c);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);$rel='bhc-image-references/snowa-'.$it['model'].'-v328.png';$dst=trailingslashit($upload['basedir']).$rel;wp_mkdir_p(dirname($dst));@unlink($dst);imagepng($out,$dst,6);imagedestroy($out);imagedestroy($im);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Snowa '.$it['model'].' transparent 4K','post_status'=>'inherit'],$dst,$id);if(!$aid)continue;update_post_meta($aid,'_wp_attached_file',$rel);update_post_meta($aid,'_wp_attachment_metadata',['width'=>$nw,'height'=>$nh,'file'=>$rel,'sizes'=>[],'image_meta'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_prompt','Exact Snowa '.$it['model'].' refrigerator product cutout, transparent background, isolated catalog view, 4K canvas.');}
 update_option('bhc_catalog_image_snowa_refrigerator_remediation_v328',['count'=>count($map),'at'=>current_time('mysql')],false);
},328);
